// Offline pixel rendering only. No application requests, model calls, hidden answer text or PNG metadata labels.
import {chromium} from '@playwright/test'
import {readFile} from 'node:fs/promises'
import {fileURLToPath} from 'node:url'
import {join} from 'node:path'
const dir=fileURLToPath(new URL('.',import.meta.url)),corpus=JSON.parse(await readFile(join(dir,'labels.json'),'utf8'))
const html=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')
const browser=await chromium.launch({headless:true,args:['--use-mock-keychain','--password-store=basic']})
try{
 const page=await browser.newPage({viewport:{width:900,height:1300},deviceScaleFactor:1})
 for(const [index,row] of corpus.cases.entries()){
  const r=JSON.parse(await readFile(join(dir,row.readingLabel),'utf8')),email=r.format==='airline-email',thermal=['restaurant-receipt','airport-cafe','thermal-receipt'].includes(r.format),photo=r.format==='photographed-receipt',invoice=r.format.includes('invoice'),blue=email?'#1d4d74':'#242927'
  const head=email?`<section class="mail"><b>From:</b> payments@${r.id}.example<br><b>To:</b> Sam Rivers &lt;synthetic-coaster-61001@example.test&gt;<br><b>Subject:</b> Your payment receipt</section>`:''
  const header=`<h1>${html(r.merchant)}</h1><div class="subtitle">${email?'AIR TRAVEL PAYMENT RECEIPT':invoice?'PAID INVOICE':r.format==='airport-cafe'?'TERMINAL 1 · FOOD COUNTER':'PURCHASE RECEIPT'}</div>`
  const address=email?'Passenger: SAM RIVERS<br>Economy cabin · BOS / ORD':r.format==='service-invoice'?'Professional services · Boston studio':r.format==='marketplace-invoice'?'Order summary · Sold to Northstar Studio':'18 Harbor Street · Boston, MA 02110'
  const ref=r.reference?`<section class="reference"><b>Sold to:</b> Northstar Studio<br><b>Work order:</b> ${html(r.reference.project)}<br><b>Client:</b> ${html(r.reference.customer)}<br><b>Deliver to:</b> ${html(r.reference.department)} team</section>`:''
  const lines=r.lineItems.map(x=>`<tr><td class="description">${html(x.description)}</td><td>${x.quantity}</td><td>${x.unitPrice}</td><td>${x.amount}</td></tr>`).join('')
  const body=`${head}<article class="${thermal?'thermal':email?'airline':invoice?'invoice':'retail'} ${photo?'photo':''}">${header}<p class="address">${address}</p><section class="facts"><div>Purchase date <b>${r.date}</b></div><div>Receipt <b>${r.id}</b></div><div>Currency <b>${r.currency}</b></div></section>${ref}<table><thead><tr><th>Purchased item</th><th>Qty</th><th>Each</th><th>Amount</th></tr></thead><tbody>${lines}</tbody></table><section class="totals"><div><span>Subtotal</span><b>${r.subtotal}</b></div><div><span>${email?'Taxes':'Sales tax'}</span><b>${r.salesTax}</b></div><div><span>Tip</span><b>${r.tip}</b></div><div class="grand"><span>TOTAL PAID ${r.currency}</span><b>${r.total}</b></div></section><p class="paid">PAID BY COMPANY CARD ending ${r.last4}<br>Payment received · Thank you</p><p class="footer">Keep this receipt for your records.<br>Synthetic demonstration transaction.</p></article>`
  await page.setContent(`<style>*{box-sizing:border-box}body{margin:0;padding:42px;background:${photo?'#d5d4cf':email?'#edf1f5':'#e8e8e2'};color:#202520;font:18px Arial,sans-serif}article{margin:0 auto;width:780px;min-height:850px;padding:40px 42px;background:#fffef9;box-shadow:0 2px 8px #0002;border:1px solid #ddd}h1{font-size:30px;color:${blue};line-height:1.15;margin:0 0 18px}.subtitle{font-size:14px;letter-spacing:1.2px;border-bottom:2px solid ${blue};padding-bottom:15px}.address{font-size:16px;line-height:1.6;margin:22px 0}.facts{font-size:16px;line-height:1.8;border-bottom:1px solid #ccc;padding-bottom:20px}.facts div{display:flex;justify-content:space-between;gap:20px}.reference{font-size:16px;line-height:1.7;margin:22px 0;padding:15px;border-left:3px solid #b8bdc0;background:#f7f7f4}table{width:100%;border-collapse:collapse;margin-top:24px;font-size:17px;line-height:1.5}th{font-size:13px;text-align:left;font-weight:normal;border-bottom:1px solid #aaa;padding-bottom:10px}td{padding:15px 0;vertical-align:top;border-bottom:1px dotted #ddd}th:not(:first-child),td:not(:first-child){text-align:right;padding-left:12px;white-space:nowrap}.description{width:58%;padding-right:16px}.totals{margin-top:22px;margin-left:28%;font-size:18px}.totals div{display:flex;justify-content:space-between;gap:22px;margin:14px 0}.grand{padding-top:17px;border-top:2px solid #555;font-size:22px;line-height:1.4}.paid{margin-top:30px;font-size:16px;line-height:1.8}.footer{font-size:13px;line-height:1.7;color:#777;margin-top:28px}.mail{width:780px;margin:0 auto 20px;padding:16px 24px;background:#fff;font-size:14px;line-height:1.7;border:1px solid #ccd3d9}.thermal{width:620px;font-family:Courier New,monospace;padding:35px}.thermal h1{font-size:28px}.thermal table{font-size:16px}.thermal .facts{font-size:14px}.thermal .totals{margin-left:0}.thermal .grand{font-size:21px}.photo{transform:rotate(${index%2?1.8:-1.5}deg);background-image:repeating-linear-gradient(158deg,transparent 0px,#00000005 37px,transparent 42px,transparent 83px);box-shadow:4px 6px 14px #0003}.airline{border-top:8px solid ${blue}}</style>${body}`)
  await page.screenshot({path:join(dir,row.receipt),fullPage:true})
 }
 console.log(`Rendered ${corpus.cases.length} frozen semantic receipt PNGs without application or provider calls`)
}finally{await browser.close()}
